def validate_safe_component(
    value: object, label: str, *, allow_hidden: bool
) -> None:
    if not isinstance(value, str):
        raise AuditContractError(f"{label} must be a string path component")
    path = Path(value)
    unsafe = (
        not value
        or value in {".", ".."}
        or (not allow_hidden and value.startswith("."))
        or path.is_absolute()
        or len(path.parts) != 1
        or "/" in value
